CREATE DATABASE IF NOT EXISTS rhd_lifecore CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rhd_lifecore;

CREATE TABLE IF NOT EXISTS profiles (uid VARCHAR(64) NOT NULL PRIMARY KEY, name VARCHAR(128) NOT NULL DEFAULT '', cash BIGINT NOT NULL DEFAULT 500, bank BIGINT NOT NULL DEFAULT 1000, job VARCHAR(64) NOT NULL DEFAULT 'unemployed', role VARCHAR(32) NOT NULL DEFAULT 'civilian', licenses_text TEXT NOT NULL, vehicles_text LONGTEXT NOT NULL, inventory_text LONGTEXT NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transactions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, uid VARCHAR(64) NOT NULL, action VARCHAR(32) NOT NULL, amount BIGINT NOT NULL DEFAULT 0, target_uid VARCHAR(64) NULL, metadata_text TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_tx_uid_created(uid, created_at));
CREATE TABLE IF NOT EXISTS vehicles (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, uid VARCHAR(64) NOT NULL, class VARCHAR(128) NOT NULL, plate VARCHAR(32) NOT NULL UNIQUE, state ENUM('garage','stored','impounded','destroyed') NOT NULL DEFAULT 'garage', position_text TEXT NULL, damage FLOAT NOT NULL DEFAULT 0, fuel FLOAT NOT NULL DEFAULT 1, metadata_text TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_vehicle_uid_state(uid, state));
CREATE TABLE IF NOT EXISTS role_whitelist (uid VARCHAR(64) NOT NULL, role VARCHAR(32) NOT NULL, enabled TINYINT(1) NOT NULL DEFAULT 1, granted_by VARCHAR(64) NULL, granted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(uid, role));
CREATE TABLE IF NOT EXISTS job_history (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, uid VARCHAR(64) NOT NULL, job VARCHAR(64) NOT NULL, changed_by VARCHAR(64) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_job_uid(uid));
